response_text:
{
  "case_id": "C01",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Why timing, not just length",
      "narration": "Short sleep duration is a known correlate of cardiometabolic disease. Sleep-timing regularity has been less studied.",
      "on_screen": "Two labels side by side: 'How long you sleep - established correlate' and 'How regular your timing is - less studied'.",
      "claim_refs": ["CL06", "CL07"]
    },
    {
      "beat": "The cohort and the score",
      "narration": "Researchers followed 41,208 adults, aged 40-69 at enrolment, for a median of 6.4 years, scoring a single 7-day accelerometry recording on a Sleep Regularity Index from 0 to 100 - how closely one day's sleep-wake pattern repeats 24 hours later.",
      "on_screen": "Cohort card: 41,208 adults; aged 40-69 at enrolment; median follow-up 6.4 years; one 7-day accelerometry window. Beside it, an SRI dial from 0 (fully irregular) to 100 (perfectly regular).",
      "claim_refs": ["CL04", "CL05"]
    },
    {
      "beat": "The headline association",
      "narration": "The least regular quintile, below 58, had a hazard ratio of 1.34, 95% confidence interval 1.18 to 1.52, for a first cardiometabolic event, versus the most regular quintile at 82 or above - an association, after adjustment including average sleep duration and shift work.",
      "on_screen": "Q5 (SRI < 58) vs Q1 (SRI >= 82): HR 1.34 (95% CI 1.18-1.52). Footer: observational association; adjusted for a listed set of covariates.",
      "claim_refs": ["CL01"]
    },
    {
      "beat": "Gradient and the mood check",
      "narration": "Hazard ratios rose across quintiles, p for trend 0.002, though the intervals for quintiles two and three include 1.00. Adjusting further for baseline depressive symptoms attenuated it to 1.27, 1.11 to 1.45.",
      "on_screen": "Quintile bars: Q1 1.00 (reference), Q2 1.06 (0.90-1.24), Q3 1.13 (0.97-1.32), Q4 1.22 (1.05-1.42), Q5 1.34 (1.18-1.52); p for trend 0.002. Q2 and Q3 intervals marked as crossing 1.00. Inset: with baseline depressive symptoms added, HR 1.27 (1.11-1.45).",
      "claim_refs": ["CL03", "CL02"]
    },
    {
      "beat": "What this cannot tell us",
      "narration": "Sleep timing was measured once, and outcomes came from record linkage. This is an observational cohort; the record says only that regularity may warrant further study.",
      "on_screen": "Limitations list: sleep timing measured once, over 7 days, not re-measured during follow-up; outcomes from hospital admission and death record linkage; prospective observational cohort, not an intervention study.",
      "claim_refs": ["CL04", "CL08", "CL01"]
    }
  ]
}
